def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1

    oppD = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            oppD += 1
        else:
            break

    look = 10
    if n < look:
        look = n
    recent_c10 = 0
    for i in range(n - look, n):
        if history[i][1] == 'C':
            recent_c10 += 1

    look5 = 5
    if n < look5:
        look5 = n
    recent_c5 = 0
    for i in range(n - look5, n):
        if history[i][1] == 'C':
            recent_c5 += 1

    coop_context = (opp_c * 2 > n) and (recent_c10 >= 5)
    very_coop = (opp_c * 10 >= n * 7) and (recent_c10 >= 7)

    if recent_c10 <= 3 and opp_c * 2 <= n:
        return 'D'

    recent_signal = False
    if n >= 2:
        start = n - 4
        if start < 0:
            start = 0
        for i in range(start, n - 1):
            if history[i][0] == 'D' and history[i + 1][1] == 'C':
                recent_signal = True
                break

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        if coop_context and recent_signal:
            return 'D'
        return 'C'

    if not coop_context:
        return 'D'

    if n >= 2:
        prev_my = history[-2][0]
    else:
        prev_my = last_my

    if prev_my == 'D':
        if oppD <= 5 and recent_c10 >= 5 and opp_c * 2 > n:
            return 'C'
        return 'D'

    if oppD == 1 and very_coop:
        return 'C'

    if oppD >= 2:
        if oppD < 4:
            return 'D'
        if oppD == 4:
            return 'C'
        return 'D'

    return 'D'
